text:
{
  "title": "سياسة الخصوصية وشروط الخدمة لشركة التقنية المتطورة المحدودة",
  "planted": [
    {
      "slot": "p1",
      "text": "لضمان تقديم تجربة مخصصة ومستمرة عند الاشتراك في النشرة الإخبارية الدورية، يتطلب التسجيل تقديم الاسم الكامل، والبريد الإلكتروني، وتاريخ الميلاد، والحالة الاجتماعية، وعدد أفراد الأسرة."
    },
    {
      "slot": "p2",
      "text": "توافق على منح الشركة حق الاستفادة من كافة البيانات والمعلومات المقدمة وتوظيفها ضمن أي نطاق تنظيمي أو تجاري تراه مناسباً لدعم عملياتها الحالية أو التطويرية المستقبلية وفقاً لما تقره الإدارة."
    },
    {
      "slot": "p3",
      "text": "تقتصر متطلبات جمع البيانات الصحية أو الجسدية حصراً على المتقدمين للوظائف التشغيلية الميدانية التي تستوجب تقارير اللياقة البدنية وفقاً لمتطلبات السلامة المهنية المعتمدة."
    }
  ],
  "neutral": [
    "تخضع كافة الرسوم المالية المعلنة للخدمات المقدمة لأحكام ضريبة القيمة المضافة وفقاً للنسب المقررة نظاماً.",
    "تتم تسوية المدفوعات المالية عبر قنوات الدفع الإلكترونية المعتمدة وربطها بالفواتير الصادرة.",
    "يحق لأي من الطرفين إنهاء هذه الاتفاقية بموجب إشعار كتابي يوجه للطرف الآخر قبل موعد الإغلاق بثلاثين يوماً على الأقل.",
    "لا تتحمل الشركة أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر التبعية الناتجة عن انقطاع الخدمة المفاجئ.",
    "تخضع هذه الشروط وتُفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية وتختص المحاكم المختصة بالفصل في النزاعات الناشئة عنها."
  ]
}
